function icon(name, cls='') { return `<span class="icon ${cls}" aria-hidden="true"><svg viewBox="0 0 24 24">${ICONS[name]||ICONS.sparkle}</svg></span>`; }
function esc(value='') { return String(value??'').replace(/[&<>"']/g,(c)=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function initials(name='GS') { return String(name).trim().split(/\s+/).slice(0,2).map((part)=>part[0]?.toUpperCase()||'').join('')||'GS'; }
const money=(value,compact=false)=>formatMoney(value,compact);
function currentUser(){return session?.role==='user'?findUser(db,session.userId):null;}
const isAdmin=()=>session?.role==='admin';
function save(){saveDatabase(db);if(session)saveSession(session);if(backendAvailable&&serverMode&&session?.role==='user')syncServerState();}
function toast(message,kind='success') { const el=document.createElement('div');el.className=`toast ${kind==='error'?'error':''}`;el.innerHTML=`<span class="toast-mark">${kind==='error'?'!':'✓'}</span><p>${esc(message)}</p>`;$('#toast-region').append(el);setTimeout(()=>el.remove(),3800); }
function pageTitle(title,description,actions=''){return `<div class="page-head"><div><h1>${esc(title)}</h1><p>${esc(description)}</p></div><div class="page-head-actions">${actions}</div></div>`;}
function sectionTitle(title,subtitle='',action=''){return `<div class="section-heading"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${action}</div>`;}
function numberFromSeed(text,min=0,max=100){let h=0;for(const c of text)h=((h<<5)-h+c.charCodeAt(0))|0;return min+Math.abs(h)%(max-min+1);}
function chartValues(seed='goal-system',count=22,low=15,high=88){return Array.from({length:count},(_,i)=>low+numberFromSeed(`${seed}:${i}`,0,high-low));}
function pathFor(values,width,height,pad=4){const min=Math.min(...values),max=Math.max(...values),range=max-min||1;return values.map((v,i)=>`${i?'L':'M'}${(pad+i*(width-pad*2)/Math.max(1,values.length-1)).toFixed(2)},${(height-pad-((v-min)/range)*(height-pad*2)).toFixed(2)}`).join(' ');}
function sparkline(values,negative=false){return `<svg class="sparkline ${negative?'down':''}" viewBox="0 0 78 27" aria-hidden="true"><path d="${pathFor(values||chartValues('stock'),78,27,3)}"/></svg>`;}
function heroChart(values=chartValues('hero',34,8,83),id='hero'){const line=pathFor(values,500,165,6),area=`${line} L494,165 L6,165 Z`;return `<svg class="hero-chart" viewBox="0 0 500 165" role="img" aria-label="Portfolio value chart"><defs><linearGradient id="${id}Area" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#a28dff" stop-opacity=".32"/><stop offset="1" stop-color="#a28dff" stop-opacity="0"/></linearGradient></defs><path class="chart-grid" d="M4 34H496M4 77H496M4 120H496"/><path class="chart-area" d="${area}" style="fill:url(#${id}Area)"/><path class="chart-line" d="${line}"/></svg>`;}
function balanceChart(id='balanceFill'){const vals=chartValues('balance-chart',30,20,84),line=pathFor(vals,600,150,4),area=`${line} L596,150 L4,150 Z`;return `<svg class="balance-chart" viewBox="0 0 600 150" preserveAspectRatio="none"><defs><linearGradient id="${id}" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#9d87ff" stop-opacity=".37"/><stop offset="1" stop-color="#9d87ff" stop-opacity="0"/></linearGradient></defs><path class="area" d="${area}"/><path class="line" d="${line}"/></svg>`;}
const currentWallet=(user)=>user?.wallet||{available:0,invested:0,earnings:0,deposits:0,withdrawals:0};
const totalGoalTarget=(user)=>(user?.goals||[]).reduce((s,g)=>s+Number(g.target||0),0);
const totalGoalCurrent=(user)=>(user?.goals||[]).reduce((s,g)=>s+Number(g.current||0),0);
function goalProgress(user){const target=totalGoalTarget(user);return target?Math.min(100,Math.round(totalGoalCurrent(user)/target*100)):0;}
function safeAvatar(name){return `<span class="avatar">${esc(initials(name))}</span>`;}
function displayDate(value,opts={month:'short',day:'numeric',year:'numeric'}){try{return new Date(value).toLocaleDateString('en-US',opts);}catch{return '—';}}
function timeAgo(value){const delta=Date.now()-new Date(value).getTime();if(delta<60000)return 'Just now';if(delta<3600000)return `${Math.floor(delta/60000)}m ago`;if(delta<86400000)return `${Math.floor(delta/3600000)}h ago`;return displayDate(value,{month:'short',day:'numeric'});}

