function adminMetric(label,value,detail,glyph='grid'){return `<article class="card admin-stat"><span class="metric-icon">${icon(glyph)}</span><small>${label}</small><strong>${value}</strong><span>${detail}</span></article>`;}
function renderAdmin(){if(!isAdmin())return `<article class="card"><div class="empty-state"><div><span class="empty-icon">${icon('shield')}</span><h3>Administrator access required</h3><p>Sign in with an administrator account to open this console.</p><button class="btn btn-primary" data-action="auth-open" data-auth-mode="signin">SIGN IN</button></div></div></article>`;const tabs=['Overview','Users','Payments','Announcements','Messages','Deposit methods','Wallet adjustments'];let body='';if(pageState.adminTab==='Overview'){const pending=db.requests.filter(r=>r.status==='Pending').length,total=db.users.reduce((s,u)=>s+Number(u.wallet?.available||0),0),goals=db.users.reduce((s,u)=>s+(u.goals?.length||0),0);body=`<section class="metric-grid">${adminMetric('REGISTERED USERS',db.users.length,'Personal Goal system accounts','user')}${adminMetric('PENDING REQUESTS',pending,'Deposits and withdrawals to review','clock')}${adminMetric('USER WALLET BALANCE',money(total,true),'Combined available balances','wallet')}${adminMetric('ACTIVE GOALS',goals,'Across all members','target')}</section><section class="grid grid-2"><article class="card card-pad"><div class="card-title-row"><div><h3>Recent members</h3><p>Latest account activity</p></div><button class="text-link" data-action="admin-tab" data-tab="Users">View all ${icon('arrow')}</button></div>${db.users.length?`<div class="activity-list">${[...db.users].sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt)).slice(0,5).map(u=>`<div class="activity-row">${safeAvatar(u.name)}<div class="activity-copy"><strong>${esc(u.name)}</strong><small>@${esc(u.username)} · joined ${displayDate(u.createdAt,{month:'short',day:'numeric'})}</small></div><button class="btn btn-ghost btn-small" data-action="user-detail" data-id="${u.id}">Inspect</button></div>`).join('')}</div>`:`<div class="empty-state"><div><h3>Member accounts will appear here</h3><p>Create an account on the public sign-up form or add a user from this console.</p><button class="btn btn-primary btn-small" data-action="user-create">Create a user</button></div></div>`}</article><article class="card card-pad"><div class="card-title-row"><div><h3>Requests to review</h3><p>Authenticate deposits and withdrawals</p></div><button class="text-link" data-action="admin-tab" data-tab="Payments">Open requests ${icon('arrow')}</button></div>${db.requests.filter(r=>r.status==='Pending').slice(0,5).map(r=>{const u=findUser(db,r.userId);return `<div class="activity-row"><span class="activity-icon">${icon(r.type==='Deposit'?'download':'arrowUp')}</span><div class="activity-copy"><strong>${esc(r.type)} · ${money(r.amount)}</strong><small>${esc(u?.name||'Unknown member')} · ${timeAgo(r.createdAt)}</small></div><span class="status status-pending">Pending</span></div>`}).join('')||`<div class="empty-state"><div><span class="empty-icon">${icon('shield')}</span><h3>All caught up</h3><p>New payment requests will appear here.</p></div></div>`}</article></section><section class="card card-pad" style="margin-top:16px"><div class="card-title-row"><div><h3>Console shortcuts</h3><p>Common administration actions</p></div></div><div class="quick-grid admin-shortcuts"><button class="quick-action" data-action="user-create"><span class="qa-icon">${icon('plus')}</span><span><strong>Create a user</strong><small>Set up a member account</small></span></button><button class="quick-action" data-action="announcement-create"><span class="qa-icon">${icon('sparkle')}</span><span><strong>Send announcement</strong><small>Share an update</small></span></button><button class="quick-action" data-action="method-create"><span class="qa-icon">${icon('wallet')}</span><span><strong>Add payment method</strong><small>Update deposit details</small></span></button><button class="quick-action" data-action="adjust-open"><span class="qa-icon">${icon('sliders')}</span><span><strong>Adjust a wallet</strong><small>Manage account balances</small></span></button></div></section>`;}else if(pageState.adminTab==='Users')body=renderAdminUsers();else if(pageState.adminTab==='Payments')body=renderAdminPayments();else if(pageState.adminTab==='Announcements')body=renderAdminAnnouncements();else if(pageState.adminTab==='Messages')body=renderAdminMessages();else if(pageState.adminTab==='Deposit methods')body=renderAdminMethods();else body=renderAdminAdjustments();return `${pageTitle('Admin Console','Platform-wide user management, wallet operations and communications.',`<button class="btn btn-danger" data-action="logout">${icon('logout')} Sign out</button>`)}<div class="tabs admin-tabs">${tabs.map(t=>`<button class="tab ${pageState.adminTab===t?'active':''}" data-action="admin-tab" data-tab="${esc(t)}">${esc(t)}${t==='Payments'&&db.requests.some(r=>r.status==='Pending')?` <span class="pill pill-yellow">${db.requests.filter(r=>r.status==='Pending').length}</span>`:''}</button>`).join('')}</div><div style="height:16px"></div>${body}`;}
function renderAdminUsers(){return `<div class="card card-pad"><div class="card-title-row" style="margin-bottom:15px"><div><h3>All users</h3><p>Inspect personal dashboards, profile settings and wallet state</p></div><button class="btn btn-primary btn-small" data-action="user-create">${icon('plus')} Create user</button></div>${db.users.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Member</th><th>Created</th><th>Available</th><th>Invested</th><th>Earnings</th><th>Goals</th><th>Actions</th></tr></thead><tbody>${db.users.map(u=>`<tr><td><div class="user-list-row">${safeAvatar(u.name)}<div><strong>${esc(u.name)}</strong><small>@${esc(u.username)} · ${esc(u.email)}</small></div></div></td><td>${displayDate(u.createdAt)}</td><td>${money(u.wallet?.available||0)}</td><td>${money(u.wallet?.invested||0)}</td><td>${money(u.wallet?.earnings||0)}</td><td>${u.goals?.length||0}</td><td><div style="display:flex;gap:5px"><button class="btn btn-soft btn-small" data-action="user-detail" data-id="${u.id}">Open data</button><button class="icon-button" title="Edit user" data-action="user-edit" data-id="${u.id}">${icon('settings')}</button><button class="icon-button negative" title="Delete user" data-action="user-delete" data-id="${u.id}">${icon('close')}</button></div></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty-state"><div><span class="empty-icon">${icon('user')}</span><h3>No user accounts yet</h3><p>Create a member account or invite users to sign up to begin managing Goal system profiles.</p><button class="btn btn-primary" data-action="user-create">Create your first user ${icon('arrow')}</button></div></div>`}</div>`;}
function requestStatus(status){return `<span class="status status-${String(status).toLowerCase()}">${esc(status)}</span>`;}
function renderAdminPayments(){const rows=[...db.requests].sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));return `<article class="card card-pad"><div class="card-title-row" style="margin-bottom:15px"><div><h3>Deposit & withdrawal requests</h3><p>Review payment references and authenticate wallet activity</p></div><div class="pill pill-yellow">${rows.filter(r=>r.status==='Pending').length} PENDING</div></div>${rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Member</th><th>Request</th><th>Method</th><th>Reference / details</th><th>Created</th><th>Amount</th><th>Status</th><th>Review</th></tr></thead><tbody>${rows.map(r=>{const u=findUser(db,r.userId);return `<tr><td><div class="user-list-row">${safeAvatar(u?.name||'Member')}<div><strong>${esc(u?.name||'Member')}</strong><small>@${esc(u?.username||'unknown')}</small></div></div></td><td>${esc(r.type)}</td><td>${esc(r.method||'—')}</td><td>${esc(r.reference||r.details||'—')}</td><td>${displayDate(r.createdAt)}</td><td>${money(r.amount)}</td><td>${requestStatus(r.status)}</td><td>${r.status==='Pending'?`<div style="display:flex;gap:5px"><button class="btn btn-success btn-small" data-action="request-approve" data-id="${r.id}">Approve</button><button class="btn btn-danger btn-small" data-action="request-reject" data-id="${r.id}">Reject</button></div>`:`<span class="muted">${esc(r.reviewNote||'Reviewed')}</span>`}</td></tr>`}).join('')}</tbody></table></div>`:`<div class="empty-state"><div><span class="empty-icon">${icon('wallet')}</span><h3>No payment requests yet</h3><p>User deposit and withdrawal requests will be listed here for review.</p></div></div>`}</article>`;}
function renderAdminAnnouncements(){return `<article class="card card-pad"><div class="card-title-row" style="margin-bottom:15px"><div><h3>Announcements</h3><p>Communicate with all members or a specific user</p></div><button class="btn btn-primary btn-small" data-action="announcement-create">${icon('plus')} New announcement</button></div>${db.announcements.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Announcement</th><th>Audience</th><th>Level</th><th>Created</th><th>Author</th><th>Actions</th></tr></thead><tbody>${[...db.announcements].sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt)).map(a=>`<tr><td><div><strong style="color:#e2e0eb">${esc(a.title)}</strong><small style="display:block;margin-top:5px;color:#858799;max-width:340px;white-space:normal;line-height:1.5">${esc(a.body)}</small></div></td><td>${a.audience==='all'?'All users':esc(findUser(db,a.audience)?.username||a.audience)}</td><td><span class="pill ${a.level==='Important'?'pill-yellow':'pill-blue'}">${esc(a.level)}</span></td><td>${displayDate(a.createdAt)}</td><td>${esc(a.author||'Admin')}</td><td><button class="btn btn-danger btn-small" data-action="announcement-delete" data-id="${a.id}">Delete</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty-state"><div><h3>No announcements</h3><p>Send your first update to members.</p></div></div>`}</article>`;}
function renderAdminMessages(){const selected=findUser(db,pageState.adminThreadUser)||db.users[0];if(selected&&!pageState.adminThreadUser)pageState.adminThreadUser=selected.id;const chat=selected?messagesFor(db,selected.id):[];if(selected)db.messages.filter(m=>m.userId===selected.id&&m.sender==='user').forEach(m=>m.read=true);return `<section class="admin-chat-layout"><article class="card admin-chat-people"><div class="card-title-row"><div><h3>Member messages</h3><p>${db.users.length} conversations</p></div></div>${db.users.length?db.users.map(u=>{const unread=db.messages.filter(m=>m.userId===u.id&&m.sender==='user'&&!m.read).length;return `<button class="admin-person ${selected?.id===u.id?'active':''}" data-action="admin-thread" data-id="${u.id}">${safeAvatar(u.name)}<span><strong>${esc(u.name)}</strong><small>@${esc(u.username)} · ${unread?`${unread} new`:'Conversation'}</small></span></button>`}).join(''):`<div class="empty-state"><div><h3>No members yet</h3><p>Member conversations will appear here.</p></div></div>`}</article><article class="card admin-chat-panel">${selected?`<div class="card-title-row"><div><h3>Conversation with ${esc(selected.name)}</h3><p>@${esc(selected.username)} · ${esc(selected.email)}</p></div><button class="btn btn-ghost btn-small" data-action="user-detail" data-id="${selected.id}">Open user data</button></div><div class="chat-box">${chat.length?chat.map(m=>`<div class="chat-bubble ${m.sender==='admin'?'mine':''}"><p>${esc(m.text)}</p><small>${m.sender==='admin'?'Admin':esc(selected.name)} · ${timeAgo(m.createdAt)}</small></div>`).join(''):`<div class="empty-state"><div><span class="empty-icon">${icon('user')}</span><h3>Start the conversation</h3><p>Send a message to ${esc(selected.name)}.</p></div></div>`}</div><form class="chat-compose" id="admin-chat-form"><input name="message" required maxlength="1000" placeholder="Write a reply…"><button class="btn btn-primary btn-icon" aria-label="Send reply">${icon('send')}</button></form>`:`<div class="empty-state"><div><span class="empty-icon">${icon('user')}</span><h3>Choose a conversation</h3><p>Select a member to view and reply to messages.</p></div></div>`}</article></section>`;}
function renderAdminMethods(){return `<article class="card card-pad"><div class="card-title-row" style="margin-bottom:15px"><div><h3>Deposit methods</h3><p>Payment instructions shown to users when they create a deposit request</p></div><button class="btn btn-primary btn-small" data-action="method-create">${icon('plus')} Add method</button></div>${db.paymentMethods.length?`<div class="payment-method-grid">${db.paymentMethods.map(m=>`<article class="payment-method"><span class="metric-icon">${icon('wallet')}</span><h3>${esc(m.name)}</h3><p>${esc(m.detail)}</p><div class="method-meta"><span>${esc(m.time||'Processing time varies')}</span><span>${esc(m.fee||'Fees may apply')}</span></div><button class="btn btn-danger btn-small" data-action="method-delete" data-id="${m.id}">Remove method</button></article>`).join('')}</div>`:`<div class="empty-state"><div><h3>No payment methods configured</h3><p>Add a deposit method so users can submit requests.</p></div></div>`}</article>`;}
function renderAdminAdjustments(){return `<section class="grid grid-2"><article class="card card-pad"><div class="card-title-row"><div><h3>Adjust a user wallet</h3><p>Add, subtract or set an account value</p></div><span class="pill pill-purple">ADMIN ONLY</span></div><p class="muted" style="font-size:10px;line-height:1.65;margin:15px 0 17px">Wallet adjustments are recorded to the user's activity ledger and reflected in their personal dashboard.</p><button class="btn btn-primary" data-action="adjust-open">${icon('sliders')} Open wallet adjustment</button></article><article class="card card-pad"><div class="card-title-row"><div><h3>Recent adjustments</h3><p>Administrative balance changes</p></div></div>${db.activity.filter(x=>x.type==='Admin adjustment').slice(0,5).map(r=>{const u=findUser(db,r.userId);return `<div class="activity-row"><span class="activity-icon">${icon('sliders')}</span><div class="activity-copy"><strong>${esc(r.title)}</strong><small>${esc(u?.username||'member')} · ${timeAgo(r.date)}</small></div><span class="activity-amount">${money(r.amount)}</span></div>`}).join('')||`<div class="empty-state"><div><h3>No adjustments recorded</h3><p>Admin wallet actions will appear here.</p></div></div>`}</article></section>`;}
function modalFrame(title,description,body,footer='',size=''){return `<div class="modal-backdrop" data-action="modal-backdrop"><section class="modal ${size}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-head"><div><h2 id="modal-title">${title}</h2>${description?`<p>${description}</p>`:''}</div><button class="icon-button" aria-label="Close dialog" data-action="modal-close">${icon('close')}</button></header>${body}${footer?`<footer class="modal-foot">${footer}</footer>`:''}</section></div>`;}
function field(label,name,value='',type='text',extra=''){return `<div class="form-field"><label for="field-${name}">${label}</label><input id="field-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;}
function renderAuthModal(){const signup=authMode==='signup';return `<div class="modal-backdrop" data-action="modal-backdrop"><section class="modal auth-modal" role="dialog" aria-modal="true" aria-labelledby="auth-heading"><aside class="auth-art"><a class="brand" href="#top"><span class="brand-mark"></span><span class="brand-word"><span>Goal</span><span>system</span></span></a><div><h2>Build toward what matters.</h2><p>Keep your goals, wallet and portfolio in focus with a workspace made for your next move.</p></div><span class="auth-art-bottom">Plan with purpose. Build with clarity.</span></aside><div class="auth-panel"><div class="auth-panel-head"><div><h2 id="auth-heading">${signup?'Create your workspace':'Welcome back'}</h2><p>${signup?'Start with your name, email and a secure password.':'Sign in to continue to your personal dashboard.'}</p></div><button class="icon-button" data-action="modal-close">${icon('close')}</button></div><div class="auth-tabs"><button class="auth-tab ${!signup?'active':''}" data-auth-mode="signin">SIGN IN</button><button class="auth-tab ${signup?'active':''}" data-auth-mode="signup">SIGN UP</button></div><form class="auth-form" id="auth-form"><div class="form-error ${authError?'show':''}" id="auth-error">${esc(authError)}</div>${signup?`<div class="form-field"><label for="auth-name">Full name</label><input id="auth-name" name="name" autocomplete="name" placeholder="Your name" required maxlength="70"></div><div class="form-field"><label for="auth-email">Email address</label><input id="auth-email" name="email" type="email" autocomplete="email" placeholder="you@example.com" required maxlength="140"></div><div class="form-field"><label for="auth-username">Username</label><input id="auth-username" name="username" autocomplete="username" placeholder="Choose a username" required minlength="3" maxlength="24" pattern="[A-Za-z0-9_.-]+"><span class="form-hint">Use 3–24 letters, numbers, dots, dashes or underscores.</span></div>`:`<div class="form-field"><label for="auth-username">Username or email</label><input id="auth-username" name="username" autocomplete="username" placeholder="Enter your username or email" required></div>`}<div class="form-field"><label for="auth-password">Password</label><div class="password-wrap"><input id="auth-password" name="password" type="password" autocomplete="${signup?'new-password':'current-password'}" placeholder="${signup?'At least 8 characters':'Enter your password'}" required ${signup?'minlength="8"':''}><button class="password-toggle" type="button" data-action="password-toggle" data-target="auth-password">Show</button></div></div>${!signup?`<div class="auth-foot-row"><button type="button" data-action="reset-open">Forgot password?</button></div>`:''}<button class="btn btn-primary auth-submit" type="submit">${signup?'SIGN UP':'SIGN IN'} ${icon('arrow')}</button><p class="auth-terms">${signup?'By creating an account, you’re ready to start planning your next milestone.':'Secure access to your personal Goal system workspace.'}</p></form></div></section></div>`;}
function productById(id){return PRODUCTS.find(p=>p.id===id);}function propertyById(id){return PROPERTIES.find(p=>p.id===id);}
function cartRows(user=currentUser()){return (user?.cart||[]).map(row=>({...row,product:productById(row.productId)})).filter(row=>row.product);}
function cartTotals(user=currentUser()){const rows=cartRows(user);let goods=0,deposits=0,shipping=0,balance=0;for(const row of rows){const price=quote(row.product.base,row.product.id,.003,2)*row.quantity;if(row.product.reservation){const deposit=price*row.product.depositRate;deposits+=deposit;balance+=price-deposit;}else{goods+=price;shipping+=Number(row.product.shipping||0)*row.quantity;}}const tax=goods*.06625;return {rows,goods,deposits,shipping,tax,due:goods+shipping+tax+deposits,balance};}
function renderProductModal(p){if(!p)return '';const price=quote(p.base,p.id,.003,2);return modalFrame(esc(p.name),esc(p.category),`<div class="modal-content"><div class="modal-product"><div class="modal-product-image"><img src="${p.image}" alt="${esc(p.name)}"></div><div><span class="pill pill-purple">${p.reservation?'RESERVATION PRODUCT':'GOAL SYSTEM COLLECTION'}</span><h2>${esc(p.name)}</h2><div class="product-rating">★ ${p.rating.toFixed(1)} <span>(${formatNumber(p.reviews)} reviews)</span></div><div class="price-large">${money(price)}</div><p class="specs">${esc(p.specs)}</p><p class="description">${esc(p.description)}</p><form class="form-grid single" id="product-add-form"><input type="hidden" name="productId" value="${p.id}"><div class="form-field"><label for="product-variant">Variant</label><select id="product-variant" name="variant">${p.variants.map(v=>`<option>${esc(v)}</option>`).join('')}</select></div><div class="form-field"><label for="product-qty">Quantity</label><input id="product-qty" name="quantity" type="number" min="1" max="20" value="1"></div><button class="btn btn-primary" type="submit">${p.reservation?`Reserve · ${money(price*p.depositRate)} deposit`:`Add to cart · ${money(price)}`} ${icon('bag')}</button></form><div class="reservation-note">${p.reservation?`A ${Math.round(p.depositRate*100)}% reservation deposit is due today. The remaining balance is calculated at checkout.`:'Shipping is calculated at checkout. Orders are stored in your recent orders after checkout.'}</div></div></div></div>`,'','modal-wide');}
function renderCartModal(){const user=currentUser(),t=cartTotals(user),orders=[...(user?.orders||[])].sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt)).slice(0,5);const content=t.rows.length?`<div>${t.rows.map(r=>`<div class="cart-line"><img src="${r.product.image}" alt="${esc(r.product.name)}"><div><strong>${esc(r.product.name)}</strong><small>${esc(r.variant)}${r.product.reservation?' · Reservation':''}</small><div class="cart-qty"><button data-action="cart-qty" data-id="${r.product.id}" data-variant="${esc(r.variant)}" data-delta="-1">−</button><span>${r.quantity}</span><button data-action="cart-qty" data-id="${r.product.id}" data-variant="${esc(r.variant)}" data-delta="1">+</button><button class="icon-button negative" style="width:26px;height:25px" data-action="cart-remove" data-id="${r.product.id}" data-variant="${esc(r.variant)}">${icon('close')}</button></div></div><div class="cart-line-price"><strong>${money(quote(r.product.base,r.product.id,.003,2)*r.quantity)}</strong><small>${r.product.reservation?`${Math.round(r.product.depositRate*100)}% due today`:money(r.product.shipping*r.quantity)+' shipping'}</small></div></div>`).join('')}</div><div class="cart-summary"><div class="summary-row"><span>Goods subtotal</span><strong>${money(t.goods)}</strong></div><div class="summary-row"><span>Reservation deposits due today</span><strong>${money(t.deposits)}</strong></div><div class="summary-row"><span>Estimated shipping</span><strong>${money(t.shipping)}</strong></div><div class="summary-row"><span>Estimated tax</span><strong>${money(t.tax)}</strong></div><div class="summary-row total"><span>Due today</span><strong>${money(t.due)}</strong></div><div class="summary-row"><span>Balance on delivery</span><strong>${money(t.balance)}</strong></div></div>`:`<div class="empty-state"><div><span class="empty-icon">${icon('bag')}</span><h3>Your cart is ready for something useful</h3><p>Add goods or reserve an electric vehicle or robot from the collection.</p><button class="btn btn-primary btn-small" data-action="modal-close">Continue shopping</button></div></div>`;const recent=orders.length?`<div style="margin-top:21px"><div class="card-title-row" style="margin-bottom:8px"><div><h3>Recent orders</h3><p>Your latest Goal system purchases</p></div></div>${orders.map(o=>`<div class="activity-row"><span class="activity-icon">${icon('bag')}</span><div class="activity-copy"><strong>${esc(o.id)} · ${o.items.length} ${o.items.length===1?'item':'items'}</strong><small>${displayDate(o.createdAt)} · ${esc(o.status)}</small></div><span class="activity-amount">${money(o.dueToday)}</span></div>`).join('')}</div>`:'';return modalFrame('Your cart',t.rows.length?'Review quantities, reservation deposits, shipping and checkout totals.':'Recent orders stay here so you can keep track of what’s next.',`<div class="modal-content">${content}${recent}</div>`,t.rows.length?`<button class="btn btn-ghost" data-action="cart-clear">Clear cart</button><button class="btn btn-primary" data-action="checkout-open">Continue to checkout ${icon('arrow')}</button>`:`<button class="btn btn-ghost" data-action="modal-close">Close</button>`,'modal-wide');}
function renderCheckoutModal(){const user=currentUser(),t=cartTotals(user);if(!t.rows.length)return renderCartModal();return modalFrame('Checkout','A few details, then your order is ready.',`<form id="checkout-form"><div class="modal-content"><div class="checkout-layout"><div class="form-grid"><div class="form-field"><label for="checkout-name">Contact name</label><input id="checkout-name" name="name" required value="${esc(user.name)}"></div><div class="form-field"><label for="checkout-email">Email</label><input id="checkout-email" name="email" type="email" required value="${esc(user.email)}"></div><div class="form-field"><label for="checkout-phone">Phone</label><input id="checkout-phone" name="phone" type="tel" required placeholder="(201) 555-0142"></div><div class="form-field"><label for="checkout-delivery">Delivery method</label><select id="checkout-delivery" name="delivery"><option>Standard delivery</option><option>Priority delivery</option><option>Pickup</option></select></div><div class="form-field full"><label for="checkout-address">Delivery address</label><input id="checkout-address" name="address" required placeholder="Street address"></div><div class="form-field"><label for="checkout-city">City</label><input id="checkout-city" name="city" required placeholder="City"></div><div class="form-field"><label for="checkout-state">State</label><input id="checkout-state" name="state" required placeholder="State"></div><div class="form-field"><label for="checkout-zip">ZIP / postal code</label><input id="checkout-zip" name="zip" required placeholder="ZIP code"></div><div class="form-field"><label for="checkout-payment">Payment method</label><select id="checkout-payment" name="payment"><option>Card on file</option><option>Wallet balance</option><option>Bank transfer</option></select></div><div class="form-field full"><label for="checkout-notes">Payment reference / notes</label><textarea id="checkout-notes" name="notes" placeholder="Optional order or payment notes"></textarea></div></div><aside class="checkout-summary"><h3 style="margin:0 0 10px;font-size:12px">Order summary</h3>${t.rows.map(r=>`<div class="summary-row"><span>${esc(r.product.name)} × ${r.quantity}</span><strong>${money(quote(r.product.base,r.product.id,.003,2)*r.quantity)}</strong></div>`).join('')}<div class="summary-row"><span>Shipping & tax</span><strong>${money(t.shipping+t.tax)}</strong></div><div class="summary-row total"><span>Due today</span><strong>${money(t.due)}</strong></div><div class="summary-row"><span>Balance on delivery</span><strong>${money(t.balance)}</strong></div></aside></div></div><footer class="modal-foot"><button class="btn btn-ghost" type="button" data-action="cart-open">Back to cart</button><button class="btn btn-primary" type="submit">Complete checkout ${icon('arrow')}</button></footer></form>`,'','modal-wide');}
function renderUserFormModal(user){const edit=Boolean(user);return modalFrame(edit?'Edit user':'Create a user',edit?'Update member profile information and account access.':'Create a new Goal system member profile.',`<form id="admin-user-form"><div class="modal-content"><div class="form-grid"><div class="form-error full" id="admin-user-error"></div>${field('Full name','name',user?.name||'','text','required maxlength="70"')}${field('Username','username',user?.username||'','text','required minlength="3" maxlength="24" pattern="[A-Za-z0-9_.-]+"')}${field('Email address','email',user?.email||'','email','required maxlength="140"')}${field(edit?'New password (optional)':'Temporary password','password','','password',edit?'minlength="8"':'required minlength="8"')}${edit?'':`<div class="form-field"><label for="admin-risk">Risk profile</label><select id="admin-risk" name="risk"><option>Balanced</option><option>Conservative</option><option>Growth</option><option>Aggressive</option></select></div>`}</div></div><footer class="modal-foot"><button class="btn btn-ghost" type="button" data-action="modal-close">Cancel</button><button class="btn btn-primary" type="submit">${edit?'Save user':'Create user'} ${icon('arrow')}</button></footer></form>`,'','modal-narrow');}
function renderUserDetailModal(user){if(!user)return '';const w=currentWallet(user),pending=(user.requests||[]).filter(r=>r.status==='Pending').length;return modalFrame(esc(user.name),`@${esc(user.username)} · Member since ${displayDate(user.createdAt)}`,`<div class="modal-content"><div class="user-detail-head">${safeAvatar(user.name)}<div><h3>${esc(user.name)}</h3><p>${esc(user.email)}</p></div><span class="pill pill-green">ACTIVE</span></div><section class="grid grid-3" style="margin-top:14px"><div class="detail-tile"><span>Available</span><strong>${money(w.available,true)}</strong></div><div class="detail-tile"><span>Invested</span><strong>${money(w.invested,true)}</strong></div><div class="detail-tile"><span>Earnings</span><strong>${money(w.earnings,true)}</strong></div></section><section class="grid grid-3" style="margin-top:9px"><div class="detail-tile"><span>Goals</span><strong>${user.goals?.length||0}</strong></div><div class="detail-tile"><span>Holdings</span><strong>${user.holdings?.length||0}</strong></div><div class="detail-tile"><span>Pending requests</span><strong>${pending}</strong></div></section><div class="user-detail-section"><h4>Goals</h4>${user.goals?.length?user.goals.map(g=>`<div class="detail-row"><span>${esc(g.name)}</span><strong>${money(g.current)} / ${money(g.target)}</strong></div>`):'<p>No financial goals created.</p>'}</div><div class="user-detail-section"><h4>Recent activity</h4>${user.activity?.length?user.activity.slice(0,5).map(r=>`<div class="detail-row"><span>${esc(r.title)}</span><strong>${timeAgo(r.date)}</strong></div>`):'<p>No recorded activity.</p>'}</div></div>`,`<button class="btn btn-ghost" data-action="user-thread" data-id="${user.id}">Message user</button><button class="btn btn-soft" data-action="user-edit" data-id="${user.id}">Edit profile</button><button class="btn btn-primary" data-action="adjust-open" data-user="${user.id}">Adjust wallet ${icon('arrow')}</button>`,'modal-wide');}
function renderAdminModalForm(type){if(type==='announcement')return modalFrame('Send an announcement','Share an update with all members or a specific user.',`<form id="announcement-form"><div class="modal-content"><div class="form-grid"><div class="form-field full"><label for="announcement-title">Title</label><input id="announcement-title" name="title" required maxlength="100" placeholder="A clear title for your update"></div><div class="form-field full"><label for="announcement-body">Body</label><textarea id="announcement-body" name="body" required maxlength="1000" placeholder="Write a useful update for your members…"></textarea></div><div class="form-field"><label for="announcement-audience">Audience</label><select id="announcement-audience" name="audience"><option value="all">All users</option>${db.users.map(u=>`<option value="${u.id}">${esc(u.name)} · @${esc(u.username)}</option>`).join('')}</select></div><div class="form-field"><label for="announcement-level">Level</label><select id="announcement-level" name="level"><option>Update</option><option>Important</option><option>Info</option></select></div></div></div><footer class="modal-foot"><button class="btn btn-ghost" type="button" data-action="modal-close">Cancel</button><button class="btn btn-primary" type="submit">Send announcement ${icon('arrow')}</button></footer></form>`,'','modal-narrow');if(type==='method')return modalFrame('Add a deposit method','Provide payment instructions and processing details for members.',`<form id="method-form"><div class="modal-content"><div class="form-grid single">${field('Method name','name','','text','required maxlength="70" placeholder="e.g. ACH transfer"')}${field('Payment details / instructions','detail','','text','required maxlength="220" placeholder="Details shared with members"')}${field('Processing time','time','','text','maxlength="70" placeholder="e.g. 1–3 business days"')}${field('Fee information','fee','','text','maxlength="80" placeholder="e.g. No platform fee"')}</div></div><footer class="modal-foot"><button class="btn btn-ghost" type="button" data-action="modal-close">Cancel</button><button class="btn btn-primary" type="submit">Add method ${icon('arrow')}</button></footer></form>`,'','modal-narrow');if(type==='adjust'){const chosen=modal.data?.userId||'';return modalFrame('Adjust a user wallet','Choose an account, balance field and adjustment method.',`<form id="adjust-form"><div class="modal-content"><div class="form-grid single"><div class="form-error" id="adjust-error"></div><div class="form-field"><label for="adjust-user">User account</label><select id="adjust-user" name="userId" required><option value="">Select a member</option>${db.users.map(u=>`<option value="${u.id}" ${chosen===u.id?'selected':''}>${esc(u.name)} · @${esc(u.username)}</option>`).join('')}</select></div><div class="form-field"><label for="adjust-field">Balance field</label><select id="adjust-field" name="field"><option value="available">Available balance</option><option value="invested">Investment value</option><option value="earnings">Earnings</option></select></div><div class="form-field"><label for="adjust-operation">Operation</label><select id="adjust-operation" name="operation"><option value="add">Add</option><option value="subtract">Subtract</option><option value="set">Set to</option></select></div>${field('Amount','amount','','number','min="0.01" step="0.01" required')}<div class="form-field"><label for="adjust-note">Reason / reference</label><input id="adjust-note" name="note" maxlength="120" placeholder="Optional adjustment note"></div></div></div><footer class="modal-foot"><button class="btn btn-ghost" type="button" data-action="modal-close">Cancel</button><button class="btn btn-primary" type="submit">Apply adjustment ${icon('arrow')}</button></footer></form>`,'','modal-narrow');}}
function renderModal(){if(!modal)return '';const user=currentUser();switch(modal.type){case'auth':return renderAuthModal();case'reset':return modalFrame('Reset your password','Confirm your account details and choose a new password.',`<form id="reset-form"><div class="modal-content"><div class="form-grid single"><div class="form-error" id="reset-error"></div>${field('Username','username','','text','required')}${field('Email address','email','','email','required')}${field('New password','password','','password','required minlength="8"')}<span class="form-hint">Use at least eight characters. Your password is stored using a salted hash.</span></div></div><footer class="modal-foot"><button class="btn btn-ghost" type="button" data-action="auth-open" data-auth-mode="signin">Back to sign in</button><button class="btn btn-primary" type="submit">Reset password ${icon('arrow')}</button></footer></form>`,'','modal-narrow');case'goal-form':{const g=user?.goals.find(x=>x.id===modal.data?.id),target=g?.target||10000,tier=TIERS.find(x=>x.name===tierFor(target));return modalFrame(g?'Edit your goal':'Create a new goal','Choose the target, timeline and monthly contribution that fit your plan.',`<form id="goal-form"><div class="modal-content"><div class="form-grid"><div class="form-field full"><label for="goal-name">Goal name</label><input id="goal-name" name="name" required maxlength="60" placeholder="e.g. First home deposit" value="${esc(g?.name||'')}"></div><div class="form-field"><label for="goal-target">Target amount</label><input id="goal-target" name="target" type="number" min="100" max="10000000" step="100" required value="${target}"><span class="form-hint">Plans start at $100 and go up to $10,000,000.</span></div><div class="form-field"><label for="goal-current">Current amount</label><input id="goal-current" name="current" type="number" min="0" max="10000000" step="50" required value="${g?.current||0}"></div><div class="form-field"><label for="goal-monthly">Monthly contribution</label><input id="goal-monthly" name="monthly" type="number" min="0" max="1000000" step="25" required value="${g?.monthly||250}"></div><div class="form-field"><label for="goal-date">Target date</label><input id="goal-date" name="targetDate" type="date" value="${esc(g?.targetDate||'')}"></div><div class="form-field"><label for="goal-risk">Risk profile</label><select id="goal-risk" name="risk">${['Conservative','Balanced','Growth','Aggressive'].map(x=>`<option ${g?.risk===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-field"><label for="goal-allocation">Allocation</label><select id="goal-allocation" name="allocation">${['Balanced portfolio','Growth portfolio','Capital preservation','Custom allocation'].map(x=>`<option ${g?.allocation===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-field full"><span id="goal-tier-hint" class="pill pill-purple">${tier?.name||'Starter'} tier · ${money(tier?.min||100)} – ${money(tier?.max||999)}</span></div></div></div><footer class="modal-foot"><button class="btn btn-ghost" type="button" data-action="modal-close">Cancel</button><button class="btn btn-primary" type="submit">${g?'Save goal':'Create goal'} ${icon('arrow')}</button></footer></form>`,'','modal-narrow');}case'goal-detail':{const g=user?.goals.find(x=>x.id===modal.data?.id);if(!g)return '';const pct=Math.min(100,g.target?g.current/g.target*100:0),remaining=Math.max(0,g.target-g.current),months=g.monthly>0?Math.ceil(remaining/g.monthly):null,rate=g.risk==='Conservative'?4:g.risk==='Growth'?8:g.risk==='Aggressive'?10:6,projection=simulatorProjection(g.monthly||0,rate,Math.max(1,Math.min(30,months?Math.ceil(months/12):10)),g.current).at(-1)?.value||g.current;return modalFrame(esc(g.name),`${esc(tierFor(g.target))} plan · ${esc(g.risk)} risk`,`<div class="modal-content"><div class="goal-detail-hero"><div><span class="muted" style="font-size:10px">CURRENT PROGRESS</span><strong>${money(g.current)} <small>of ${money(g.target)}</small></strong><div class="progress-track"><span style="width:${pct}%"></span></div></div><div class="goal-detail-percent">${pct.toFixed(1)}%</div></div><div class="grid grid-2" style="margin-top:14px"><div class="detail-tile"><span>Monthly contribution</span><strong>${money(g.monthly)}</strong></div><div class="detail-tile"><span>Target date</span><strong>${g.targetDate?displayDate(g.targetDate,{month:'short',year:'numeric'}):'Not set'}</strong></div><div class="detail-tile"><span>Projected at ${rate}%</span><strong>${money(projection,true)}</strong></div><div class="detail-tile"><span>Funding remaining</span><strong>${money(remaining,true)}</strong></div><div class="detail-tile"><span>Allocation</span><strong>${esc(g.allocation||'Balanced portfolio')}</strong></div><div class="detail-tile"><span>Estimated timeline</span><strong>${months?`${months} months`:'Set a contribution'}</strong></div></div><article class="projection-note"><span class="pill pill-blue">ILLUSTRATIVE SCENARIO</span><p>At a ${money(g.monthly)} monthly contribution and ${rate}% assumed annual return, the projected value could reach ${money(projection)}. Your contributions, time horizon and market conditions shape the outcome.</p></article></div>`,`<button class="btn btn-ghost" data-action="goal-form" data-id="${g.id}">Edit goal</button><button class="btn btn-primary" data-action="invest" data-goal="${g.id}">Add funds ${icon('arrow')}</button>`,'modal-narrow');}case'property-detail':{const p=propertyById(modal.data?.id);if(!p)return '';const price=quote(p.base,p.id,.012,p.type==='REIT'?2:0),saved=user?.savedProperties.includes(p.id),match=user?.goals.slice().sort((a,b)=>Math.abs(a.target-p.base)-Math.abs(b.target-p.base))[0];return modalFrame(esc(p.name),`${esc(p.type)} · ${esc(p.city)}, ${esc(p.state)}`,`<div class="modal-content"><div class="property-detail-image"><img src="${p.image}" alt="${esc(p.name)} exterior"></div><div class="property-detail-title"><div><h2>${esc(p.name)}</h2><p>${esc(p.address)}, ${esc(p.city)}, ${esc(p.state)}</p></div><strong>${money(price)}${p.type==='REIT'?'<small> / share</small>':''}</strong></div><p class="property-detail-copy">${esc(p.description)}</p><div class="grid grid-2"><div class="detail-tile"><span>Price</span><strong>${money(price)}</strong></div><div class="detail-tile"><span>Type & status</span><strong>${esc(p.type)} · ${esc(p.status)}</strong></div>${p.beds?`<div class="detail-tile"><span>Property size</span><strong>${p.beds} beds · ${p.baths} baths · ${formatNumber(p.sqft)} sq ft</strong></div>`:`<div class="detail-tile"><span>Indicated yield</span><strong>${p.capRate}% annual</strong></div>`}${p.mortgage?`<div class="detail-tile"><span>Mortgage estimate</span><strong>${money(p.mortgage)} / month</strong></div>`:''}${p.rental?`<div class="detail-tile"><span>Rental estimate</span><strong>${money(p.rental)} / month</strong></div>`:''}${p.nightly?`<div class="detail-tile"><span>Short-stay estimate</span><strong>${money(p.nightly)} / night</strong></div>`:''}<div class="detail-tile"><span>Down payment options</span><strong>${p.down.map(n=>`${n}%`).join(' · ')}</strong></div><div class="detail-tile"><span>Funding match</span><strong>${match?esc(match.name):'Create a goal to compare'}</strong></div></div></div>`,`<button class="btn ${saved?'btn-ghost':'btn-soft'}" data-action="save-property" data-id="${p.id}">${saved?'♥ Saved':'♡ Save property'}</button><button class="btn btn-primary" data-action="property-funding" data-id="${p.id}">Match to a goal ${icon('arrow')}</button>`,'modal-wide');}case'product-detail':return renderProductModal(productById(modal.data?.id));case'cart':return renderCartModal();case'checkout':return renderCheckoutModal();
case'deposit':return modalFrame('Add funds','Create a deposit request. Your wallet is updated after administrator authentication.',`<form id="deposit-form"><div class="modal-content"><div class="form-grid single"><div class="form-error" id="deposit-error"></div>${field('Amount','amount','','number','min="10" step="0.01" required placeholder="Enter amount"')}<div class="form-field"><label for="deposit-method">Payment method</label><select id="deposit-method" name="method" required>${db.paymentMethods.map(m=>`<option value="${m.id}">${esc(m.name)} · ${esc(m.time||'Processing varies')}</option>`).join('')}</select></div>${field('Payment reference / sender name','reference','','text','maxlength="100" placeholder="Transfer reference or sender name"')}<span class="form-hint">${esc(db.paymentMethods[0]?.detail||'Payment details will be shared after you submit your request.')}</span></div></div><footer class="modal-foot"><button class="btn btn-ghost" type="button" data-action="modal-close">Cancel</button><button class="btn btn-primary" type="submit">Submit deposit request ${icon('arrow')}</button></footer></form>`,'','modal-narrow');
case'withdraw':return modalFrame('Withdraw funds','Choose a destination. Withdrawals are reviewed before funds leave your wallet.',`<form id="withdraw-form"><div class="modal-content"><div class="wallet-inline"><span>Available balance</span><strong>${money(user?.wallet?.available||0)}</strong></div><div class="form-grid single" style="margin-top:14px"><div class="form-error" id="withdraw-error"></div>${field('Amount','amount','','number',`min="10" max="${user?.wallet?.available||0}" step="0.01" required`)}${field('Account holder name','holder',user?.name||'','text','required maxlength="90"')}${field('Bank / wallet details','details','','text','required maxlength="160" placeholder="Bank, account or wallet destination"')}${field('Payment reference / note','reference','','text','maxlength="100" placeholder="Optional note"')}</div></div><footer class="modal-foot"><button class="btn btn-ghost" type="button" data-action="modal-close">Cancel</button><button class="btn btn-primary" type="submit">Request withdrawal ${icon('arrow')}</button></footer></form>`,'','modal-narrow');
case'transfer':return modalFrame('Transfer to a member','Move funds instantly to another registered Goal system username.',`<form id="transfer-form"><div class="modal-content"><div class="wallet-inline"><span>Available balance</span><strong>${money(user?.wallet?.available||0)}</strong></div><div class="form-grid single" style="margin-top:14px"><div class="form-error" id="transfer-error"></div>${field('Recipient username','username','','text','required autocomplete="off" placeholder="e.g. jordan.smith"')}${field('Amount','amount','','number',`min="1" max="${user?.wallet?.available||0}" step="0.01" required`)}${field('Note','note','','text','maxlength="100" placeholder="What is this transfer for?"')}<span class="form-hint">The recipient must have an active registered account. Transfers are immediate and recorded for both members.</span></div></div><footer class="modal-foot"><button class="btn btn-ghost" type="button" data-action="modal-close">Cancel</button><button class="btn btn-primary" type="submit">Send transfer ${icon('send')}</button></footer></form>`,'','modal-narrow');
case'invest':return modalFrame('Invest from wallet','Move available funds into your portfolio and optionally align it to a goal.',`<form id="invest-form"><div class="modal-content"><div class="wallet-inline"><span>Available balance</span><strong>${money(user?.wallet?.available||0)}</strong></div><div class="form-grid single" style="margin-top:14px"><div class="form-error" id="invest-error"></div>${field('Investment amount','amount','','number',`min="10" max="${user?.wallet?.available||0}" step="0.01" required`)}<div class="form-field"><label for="invest-class">Primary asset class</label><select id="invest-class" name="assetClass">${['US Equity','International Equity','Fixed Income','Real Estate','Commodities','Cash'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="form-field"><label for="invest-goal">Apply to a goal</label><select id="invest-goal" name="goalId"><option value="">General portfolio</option>${(user?.goals||[]).map(g=>`<option value="${g.id}" ${g.id===modal.data?.goalId?'selected':''}>${esc(g.name)}</option>`).join('')}</select></div><span class="form-hint">Invested funds are reflected in the portfolio and transaction ledger.</span></div></div><footer class="modal-foot"><button class="btn btn-ghost" type="button" data-action="modal-close">Cancel</button><button class="btn btn-primary" type="submit">Confirm investment ${icon('arrow')}</button></footer></form>`,'','modal-narrow');
case'wallet':{const requests=[...(user?.requests||[])].sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));return modalFrame('Wallet overview','Your available balance, payment requests and transfer history.',`<div class="modal-content"><div class="wallet-hero"><span>AVAILABLE BALANCE</span><strong>${money(user?.wallet?.available||0)}</strong><div class="wallet-hero-actions"><button class="btn btn-primary btn-small" data-action="deposit">${icon('plus')} Add funds</button><button class="btn btn-ghost btn-small" data-action="withdraw">Withdraw</button><button class="btn btn-ghost btn-small" data-action="transfer">Transfer</button></div></div><div class="grid grid-2" style="margin-top:13px"><div class="detail-tile"><span>Total invested</span><strong>${money(user?.wallet?.invested||0)}</strong></div><div class="detail-tile"><span>Earnings</span><strong class="positive">${money(user?.wallet?.earnings||0)}</strong></div><div class="detail-tile"><span>Total deposits</span><strong>${money(user?.wallet?.deposits||0)}</strong></div><div class="detail-tile"><span>Total withdrawals</span><strong>${money(user?.wallet?.withdrawals||0)}</strong></div></div><h3 style="font-size:12px;margin:21px 0 8px">Requests & transfers</h3>${requests.length?requests.map(r=>`<div class="activity-row"><span class="activity-icon">${icon(r.type==='Deposit'?'download':r.type==='Withdrawal'?'arrowUp':'send')}</span><div class="activity-copy"><strong>${esc(r.type)} · ${money(r.amount)}</strong><small>${esc(r.method||r.reference||'Wallet')} · ${displayDate(r.createdAt)}</small></div>${requestStatus(r.status)}</div>`).join(''):`<div class="empty-state"><div><h3>No wallet activity yet</h3><p>Your payment requests and transfers will appear here.</p></div></div>`}</div>`,`<button class="btn btn-ghost" data-action="modal-close">Close</button>`,'modal-wide');}
case'chat':{const messages=messagesFor(db,user.id);return modalFrame('Chat with Admin','A private conversation about your account and requests.',`<div class="modal-content"><div class="chat-box" id="user-chat-box">${messages.length?messages.map(m=>`<div class="chat-bubble ${m.sender==='user'?'mine':''}"><p>${esc(m.text)}</p><small>${m.sender==='user'?'You':'Admin'} · ${timeAgo(m.createdAt)}</small></div>`).join(''):`<div class="empty-state"><div><span class="empty-icon">${icon('user')}</span><h3>Your conversation starts here</h3><p>Send a message to the Goal system admin team.</p></div></div>`}</div><form class="chat-compose" id="user-chat-form"><input name="message" required maxlength="1000" placeholder="Write a message…"><button class="btn btn-primary btn-icon" aria-label="Send message">${icon('send')}</button></form></div>`,`<button class="btn btn-ghost" data-action="modal-close">Close</button>`,'modal-narrow');}
case'user-create':return renderUserFormModal(null);case'user-edit':return renderUserFormModal(findUser(db,modal.data?.id));case'user-detail':return renderUserDetailModal(findUser(db,modal.data?.id));case'announcement':case'method':case'adjust':return renderAdminModalForm(modal.type);
case'notifications':if(isAdmin())return modalFrame('Pending requests','Payment requests awaiting administrator review.',`<div class="modal-content">${db.requests.filter(r=>r.status==='Pending').map(r=>`<div class="activity-row"><span class="activity-icon">${icon(r.type==='Deposit'?'download':'arrowUp')}</span><div class="activity-copy"><strong>${esc(r.type)} · ${money(r.amount)}</strong><small>${esc(findUser(db,r.userId)?.name||'Member')} · ${timeAgo(r.createdAt)}</small></div>${requestStatus(r.status)}</div>`).join('')||'<div class="empty-state"><div><h3>Nothing to review</h3><p>All payment requests have been reviewed.</p></div></div>'}</div>`,`<button class="btn btn-primary" data-action="admin-tab" data-tab="Payments">Open payments</button>`,'modal-narrow');return modalFrame('Notifications','Important updates connected to your workspace.',`<div class="modal-content">${visibleAnnouncements(db,user).map(a=>`<div class="announcement-item"><span class="pill ${a.level==='Important'?'pill-yellow':'pill-blue'}">${esc(a.level)}</span><h4>${esc(a.title)}</h4><p>${esc(a.body)}</p><small class="muted">${displayDate(a.createdAt)} · ${esc(a.author||'Admin')}</small></div>`).join('')||'<div class="empty-state"><div><h3>You’re all caught up</h3><p>New announcements will appear here.</p></div></div>'}</div>`,`<button class="btn btn-ghost" data-action="modal-close">Close</button>`,'modal-narrow');
case'public-nav':return modalFrame('Explore Goal system','Choose a space to explore. Sign in to open your personal workspace.',`<div class="modal-content"><div class="public-link-list">${[['Dashboard','grid'],['Goals','target'],['Properties','building'],['Stock Market','chart'],['Crypto Trading','coin'],['Shop','bag'],['Advice','sparkle']].map(([l,i])=>`<button class="public-link" data-route="${l==='Advice'?'Home':l}" ${l==='Advice'?'data-scroll="advice"':''}>${icon(i)}<span>${l}</span>${icon('arrow')}</button>`).join('')}</div></div>`,`<button class="btn btn-ghost" data-action="modal-close">Close</button>`,'modal-narrow');
case'confirm':return modalFrame(modal.data.title||'Are you sure?',modal.data.body||'This action cannot be undone.',`<div class="modal-content"><div class="confirm-panel"><span class="empty-icon">${icon('shield')}</span><p>${esc(modal.data.body||'This action cannot be undone.')}</p></div></div>`,`<button class="btn btn-ghost" data-action="modal-close">Cancel</button><button class="btn btn-danger" data-action="confirm-action">${esc(modal.data.confirmLabel||'Confirm')}</button>`,'modal-narrow');default:return '';}}
function routeContent(){if(isAdmin()){if(['Admin Console','Dashboard'].includes(currentRoute))return renderAdmin();if(currentRoute==='Settings')return renderSettings();return renderAdmin();}switch(currentRoute){case'Dashboard':return renderDashboard();case'Goals':return renderGoals();case'Portfolio':return renderPortfolio();case'Stock Market':return renderStockMarket();case'Crypto Trading':return renderCrypto();case'Properties':return renderProperties();case'Shop':return renderShop();case'Activity':return renderActivityPage();case'Simulator':return renderSimulator();case'Settings':return renderSettings();default:return renderDashboard();}}
function render(){if(session?.role==='user'&&!findUser(db,session.userId)){session=null;saveSession(null);}if(!session){currentRoute='Home';root.innerHTML=renderLanding()+(modal?renderModal():'');}else root.innerHTML=appShell(routeContent());if(modal){const target=modal.type==='auth'?'#auth-username':modal.type==='transfer'?'#field-username':null;if(target)setTimeout(()=>$(target)?.focus(),20);}}
function setModal(type,data=null){modal={type,data};if(type==='auth'){authMode=data?.mode||'signin';authError='';}render();}
function closeModal(){modal=null;render();}
function navigate(route){if(route==='Admin Console'&&!isAdmin()){setModal('auth',{mode:'signin'});authError='Administrator access is available to the Admin account.';render();return;}if(!session&&!['Home','Advice'].includes(route)){setModal('auth',{mode:'signin'});return;}currentRoute=['Home','Advice'].includes(route)?'Home':route;modal=null;render();if(route==='Advice')setTimeout(()=>$('#advice')?.scrollIntoView({behavior:'smooth'}),80);}
let syncTimer=null;
async function syncServerState(){clearTimeout(syncTimer);syncTimer=setTimeout(async()=>{if(!backendAvailable||!serverMode||session?.role!=='user')return;const u=currentUser();if(!u)return;const safe={goals:u.goals,holdings:u.holdings,cart:u.cart,orders:u.orders,savedProperties:u.savedProperties,watchlist:u.watchlist,settings:u.settings,profile:{name:u.name,email:u.email}};try{await apiRequest('/state',{method:'PUT',body:{state:safe}});}catch(error){console.warn('Workspace sync paused:',error.message);}},250);}
async function refreshServerSession(){backendAvailable=await apiHealth();if(!backendAvailable)return;try{const result=await apiRequest('/auth/session');if(result?.user){serverMode=true;serverUser=result.user;session={role:result.user.role==='admin'?'admin':'user',userId:result.user.role==='admin'?undefined:result.user.id,startedAt:new Date().toISOString()};if(result.user.role==='user')mergeServerUser(result);saveSession(session);render();if(result.user.role==='admin')loadAdminServerData();}else if(session){session=null;saveSession(null);render();}}catch(error){if(session){session=null;saveSession(null);currentRoute='Home';render();}}}
function mergeServerUser(result){const raw=result.user||result;let user=findUser(db,raw.id);if(!user){user=createUserRecord({name:raw.name||'Member',username:raw.username||'member',email:raw.email||'',passwordHash:null});user.id=raw.id;db.users.push(user);}Object.assign(user,{id:raw.id,username:raw.username,name:raw.name,email:raw.email,role:'user',wallet:raw.wallet||user.wallet,createdAt:raw.createdAt||user.createdAt});const state=result.state||{};for(const key of ['goals','cart','orders','savedProperties','watchlist','settings'])if(state[key]!==undefined)user[key]=state[key];if(state.holdings!==undefined)user.holdings=state.holdings;if(state.activity!==undefined)user.activity=state.activity;if(state.requests!==undefined)user.requests=state.requests;if(Array.isArray(state.announcements))db.announcements=state.announcements;if(Array.isArray(state.paymentMethods))db.paymentMethods=state.paymentMethods;db.requests=[...db.requests.filter(r=>r.userId!==user.id),...(state.requests||[])];saveDatabase(db);return user;}
function setAuthenticated(user){session={role:user.role||'user',userId:user.role==='user'?user.id:undefined,startedAt:new Date().toISOString()};saveSession(session);currentRoute=user.role==='admin'?'Admin Console':'Dashboard';modal=null;authError='';save();render();if(user.role==='admin'&&backendAvailable)loadAdminServerData();}
async function submitAuth(form){const data=new FormData(form),username=String(data.get('username')||'').trim(),password=String(data.get('password')||'');authError='';if(!username||!password){authError='Enter your username and password to continue.';render();return;}if(authMode==='signin'){
 if(backendAvailable){try{const response=await apiRequest('/auth/sign-in',{method:'POST',body:{username,password}});serverMode=true;if(response.user?.role==='admin'){setAuthenticated({role:'admin'});toast('Signed in to the Admin Console.');return;}const state=await apiRequest('/state');const user=mergeServerUser(state);setAuthenticated(user);toast(`Welcome back, ${user.name.split(' ')[0]}.`);return;}catch(error){authError=error.message||'Those sign-in details didn’t match an account.';render();return;}}
 if(username.toLowerCase()==='admin'&&await isAdminPassword(password)){serverMode=false;setAuthenticated({role:'admin'});toast('Signed in to the Admin Console.');return;}
 const user=userByUsername(db,username);if(!user||!await verifyPassword(password,user.passwordHash)){authError='Those sign-in details didn’t match an account. Check them and try again.';render();return;}serverMode=false;setAuthenticated(user);toast(`Welcome back, ${user.name.split(' ')[0]}.`);return;
 }
 const name=String(data.get('name')||'').trim(),email=String(data.get('email')||'').trim().toLowerCase();if(username.toLowerCase()==='admin'){authError='That username is reserved. Choose a different username.';render();return;}if(!/^[a-zA-Z0-9_.-]{3,24}$/.test(username)){authError='Use 3–24 letters, numbers, dots, dashes or underscores for your username.';render();return;}if(!name||!email.includes('@')){authError='Enter your name and a valid email address.';render();return;}if(!isStrongEnough(password)){authError='Choose a password with at least eight characters.';render();return;}if(userByUsername(db,username)){authError='That username or email is already registered.';render();return;}
 const hash=await makePasswordHash(password);if(backendAvailable){try{const response=await apiRequest('/auth/sign-up',{method:'POST',body:{name,email,username,password}});serverMode=true;const merged=mergeServerUser({user:response.user,state:response.state||{}});setAuthenticated(merged);toast('Your personal workspace is ready.');return;}catch(error){authError=error.message||'Unable to create your account.';render();return;}}
 const user=createUserRecord({name,email,username,passwordHash:hash});db.users.push(user);addActivity(db,user,'Account','Goal system account created',0,{note:'Your workspace is ready.'});serverMode=false;setAuthenticated(user);toast('Your personal workspace is ready.');
}
async function savePasswordReset(form){const data=new FormData(form),username=String(data.get('username')||'').trim(),email=String(data.get('email')||'').trim().toLowerCase(),password=String(data.get('password')||''),error=$('#reset-error');if(!isStrongEnough(password)){error.textContent='Choose a password with at least eight characters.';error.classList.add('show');return;}if(backendAvailable){try{await apiRequest('/auth/reset',{method:'POST',body:{username,email,password}});}catch(issue){error.textContent=issue.message;error.classList.add('show');return;}}const user=userByUsername(db,username);if(user&&user.email.toLowerCase()===email)user.passwordHash=await makePasswordHash(password);else if(!backendAvailable){error.textContent='We could not match that username and email to an account.';error.classList.add('show');return;}saveDatabase(db);modal={type:'auth',data:{mode:'signin'}};authMode='signin';authError='Password updated. Sign in with your new password.';render();}
function createRequest(user,type,amount,extra={}){const req={id:newId('req'),userId:user.id,type,amount:Number(amount),status:'Pending',createdAt:new Date().toISOString(),...extra};db.requests.push(req);user.requests||=[];user.requests.push({...req});addActivity(db,user,`${type} request`,`${type} request submitted`,0,{note:`${money(amount)} · Awaiting review`});save();return req;}
function investAmount(user,amount,assetClass,goalId=''){const value=Number(amount);if(value<10)throw Error('Enter an investment amount of at least $10.');if(value>Number(user.wallet.available||0))throw Error('The amount is greater than your available wallet balance.');user.wallet.available-=value;user.wallet.invested+=value;const map=[['US Equity','GVUS',.43,9.8,.04],['International Equity','GVIX',.18,6.4,.12],['Fixed Income','GVFI',.16,3.1,.08],['Real Estate','GVRE',.11,5.6,.18],['Commodities','GVCO',.07,4.3,.2],['Cash','GVCS',.05,0,0]],match=map.find(x=>x[0]===assetClass)||map[0];const existing=user.holdings.find(h=>h.assetClass===match[0]),gain=dailyChange(match[1],.12)/100;if(existing){existing.value+=value*(1+gain);existing.costBasis+=value;existing.ytd=match[3];existing.expenseRatio=match[4];}else user.holdings.push({id:newId('holding'),assetClass:match[0],ticker:match[1],name:`${match[0]} allocation`,value:value*(1+gain),costBasis:value,ytd:match[3],expenseRatio:match[4]});const goal=user.goals.find(g=>g.id===goalId);if(goal)goal.current=Math.min(goal.target,Number(goal.current)+value);addActivity(db,user,'Investment',goal?`Investment toward ${goal.name}`:`Portfolio investment · ${match[0]}`,-value,{note:goal?`Goal contribution · ${goal.name}`:`${match[0]} allocation`});save();}
function createTransfer(sender,username,amount,note=''){const recipient=userByUsername(db,username),value=Number(amount);if(!recipient)throw Error('We could not find a registered member with that username.');if(recipient.id===sender.id)throw Error('Choose another member. You cannot transfer funds to yourself.');if(!(value>0))throw Error('Enter an amount greater than zero.');if(value>Number(sender.wallet.available||0))throw Error('The amount is greater than your available wallet balance.');sender.wallet.available-=value;sender.wallet.transfersOut=(sender.wallet.transfersOut||0)+value;recipient.wallet.available+=value;recipient.wallet.transfersIn=(recipient.wallet.transfersIn||0)+value;const ref=newId('tr');addActivity(db,sender,'Transfer',`Transfer to @${recipient.username}`,-value,{note,reference:ref,counterparty:recipient.username});addActivity(db,recipient,'Transfer',`Transfer from @${sender.username}`,value,{note,reference:ref,counterparty:sender.username});db.requests.push({id:ref,userId:sender.id,recipientId:recipient.id,type:'Transfer',amount:value,status:'Completed',createdAt:new Date().toISOString(),reference:ref,note});sender.requests.push({id:ref,type:'Transfer sent',amount:value,status:'Completed',createdAt:new Date().toISOString(),reference:ref,counterparty:recipient.username});recipient.requests.push({id:ref,type:'Transfer received',amount:value,status:'Completed',createdAt:new Date().toISOString(),reference:ref,counterparty:sender.username});save();return recipient;}
function createAdminUserLocal(form){return adminUserSubmit(form);}
function createConfirm({title,body,label='Confirm',fn}){setModal('confirm',{title,body,confirmLabel:label,onConfirm:fn});}
function toggleSavedProperty(id){const u=currentUser();if(!u)return;u.savedProperties||=[];const has=u.savedProperties.includes(id);u.savedProperties=has?u.savedProperties.filter(x=>x!==id):[...u.savedProperties,id];save();toast(has?'Property removed from saved items.':'Property saved to your collection.');render();}
function addProductToCart(form){const user=currentUser(),values=new FormData(form),p=productById(values.get('productId'));if(!p)return;const variant=String(values.get('variant')||p.variants[0]),qty=Math.min(20,Math.max(1,Number(values.get('quantity')||1))),row=user.cart.find(r=>r.productId===p.id&&r.variant===variant);if(row)row.quantity=Math.min(20,row.quantity+qty);else user.cart.push({productId:p.id,variant,quantity:qty});save();modal={type:'cart'};toast(`${p.name} added to your ${p.reservation?'reservations':'cart'}.`);render();}
function updateCartQty(id,variant,delta){const u=currentUser(),row=u.cart.find(r=>r.productId===id&&r.variant===variant);if(!row)return;row.quantity+=Number(delta);if(row.quantity<=0)u.cart=u.cart.filter(x=>x!==row);else row.quantity=Math.min(20,row.quantity);save();render();}
async function sendCheckout(form){const user=currentUser(),values=new FormData(form),t=cartTotals(user);if(!t.rows.length)return;const delivery=String(values.get('delivery')||'Standard delivery'),shipping=delivery==='Pickup'?0:t.shipping+(delivery==='Priority delivery'?25:0),due=t.goods+shipping+t.tax+t.deposits,balance=t.balance,payment=String(values.get('payment')||'Card on file');if(payment==='Wallet balance'&&due>user.wallet.available){toast('Your available wallet balance does not cover the due-today total.','error');return;}if(payment==='Wallet balance'){try{await apiMutation('/wallet/payment',{amount:due,title:'Marketplace order payment',note:'Wallet checkout'});}catch(error){toast(error.message,'error');return;}user.wallet.available-=due;addActivity(db,user,'Payment','Marketplace order payment',-due,{note:'Wallet checkout'});}const order={id:`GS-${new Date().toISOString().slice(2,10).replaceAll('-','')}-${Math.random().toString(36).slice(2,6).toUpperCase()}`,createdAt:new Date().toISOString(),status:'Received',items:t.rows.map(r=>({productId:r.product.id,name:r.product.name,variant:r.variant,quantity:r.quantity,unitPrice:quote(r.product.base,r.product.id,.003,2),reservation:r.product.reservation})),contact:{name:values.get('name'),email:values.get('email'),phone:values.get('phone'),delivery,address:values.get('address'),city:values.get('city'),state:values.get('state'),zip:values.get('zip')},payment,reference:String(values.get('notes')||''),goods:t.goods,shipping,tax:t.tax,dueToday:due,balanceOnDelivery:balance};user.orders.unshift(order);user.cart=[];addActivity(db,user,'Payment',`Marketplace order · ${order.id}`,-due,{note:`${order.items.length} items · ${payment}`});save();modal=null;toast(`Order ${order.id} is confirmed.`);render();}
function markRequest(req,status,note){req.status=status;req.reviewedAt=new Date().toISOString();req.reviewNote=note;const u=findUser(db,req.userId);if(u){const copy=u.requests.find(x=>x.id===req.id);if(copy)Object.assign(copy,req);if(status==='Approved'&&req.type==='Deposit'){u.wallet.available=Number(u.wallet.available||0)+Number(req.amount);u.wallet.deposits=Number(u.wallet.deposits||0)+Number(req.amount);addActivity(db,u,'Deposit','Admin-authenticated deposit',Number(req.amount),{note:req.method||'Deposit'});}else if(status==='Approved'&&req.type==='Withdrawal'){if(req.amount>u.wallet.available){req.status='Rejected';req.reviewNote='Insufficient available balance';if(copy)Object.assign(copy,req);return;}u.wallet.available-=Number(req.amount);u.wallet.withdrawals=Number(u.wallet.withdrawals||0)+Number(req.amount);addActivity(db,u,'Withdrawal','Admin-authenticated withdrawal',-Number(req.amount),{note:req.reference||'Withdrawal'});}else addActivity(db,u,req.type,`${req.type} request ${status.toLowerCase()}`,0,{note});}save();}

async function createAdminUser(form) {
  const values=new FormData(form), name=String(values.get('name')||'').trim(), username=String(values.get('username')||'').trim(), email=String(values.get('email')||'').trim().toLowerCase(), password=String(values.get('password')||'');
  const error=$('#admin-user-error');
  if (!/^[a-zA-Z0-9_.-]{3,24}$/.test(username) || username.toLowerCase()==='admin') { error.textContent='Choose a unique username using 3–24 letters, numbers, dots, dashes or underscores.'; error.classList.add('show'); return; }
  if (!name || !email.includes('@')) { error.textContent='Enter a name and valid email address.'; error.classList.add('show'); return; }
  const existing=modal.data?.id?findUser(db,modal.data.id):null;
  const dupe=db.users.find((u)=>u.id!==existing?.id&&(u.username.toLowerCase()===username.toLowerCase()||u.email.toLowerCase()===email));
  if (dupe) { error.textContent='That username or email is already registered.'; error.classList.add('show'); return; }
  if (!existing && !isStrongEnough(password)) { error.textContent='Temporary password must be at least eight characters.'; error.classList.add('show'); return; }
  let remoteUser=null;
  if(backendAvailable&&serverMode){try{const payload={name,username,email,...(password?{password}:{})};if(existing)await apiMutation(`/admin/users/${existing.id}`,payload,'PUT');else remoteUser=await apiMutation('/admin/users',payload);}catch(error){error.textContent=error.message;error.classList.add('show');return;}}
  if (existing) {
    existing.name=name; existing.username=username; existing.email=email;
    if (password) existing.passwordHash=await makePasswordHash(password);
    save(); modal=null; toast('User profile updated.'); render(); return;
  }
  const user=createUserRecord({name,username,email,passwordHash:await makePasswordHash(password)});
  if(remoteUser?.user?.id)user.id=remoteUser.user.id;
  if (values.get('risk')) user.settings.risk=String(values.get('risk'));
  db.users.push(user); addActivity(db,user,'Account','Account created by Admin',0,{note:'Welcome to Goal system.'});
  save(); modal=null; pageState.adminTab='Users'; toast(`Account created for @${username}.`); render();
}
function removeUser(userId) {
  const user=findUser(db,userId); if(!user)return;
  if(backendAvailable&&serverMode)apiMutation(`/admin/users/${userId}`,{},'DELETE').catch(error=>toast(error.message,'error'));
  db.users=db.users.filter((u)=>u.id!==userId); db.requests=db.requests.filter((r)=>r.userId!==userId&&r.recipientId!==userId); db.messages=db.messages.filter((m)=>m.userId!==userId); db.announcements=db.announcements.filter((a)=>a.audience!==userId); save(); modal=null; toast(`${user.name}'s account was removed.`); render();
}
function approveRequest(requestId, approve) {
  const request=db.requests.find((r)=>r.id===requestId); if(!request||request.status!=='Pending')return;
  if(backendAvailable&&serverMode)apiMutation(`/admin/requests/${requestId}`,{status:approve?'Approved':'Rejected'}).catch(error=>toast(error.message,'error'));
  const user=findUser(db,request.userId); if(!user)return;
  if (approve && request.type==='Withdrawal' && Number(request.amount)>Number(user.wallet.available||0)) { request.status='Rejected'; request.reviewNote='Insufficient available balance at review'; request.reviewedAt=new Date().toISOString(); requestCopyForUser(user,request); save(); toast('Withdrawal request was rejected because the available balance is insufficient.', 'error'); render(); return; }
  request.status=approve?'Approved':'Rejected'; request.reviewedAt=new Date().toISOString(); request.reviewNote=approve?'Authenticated by Admin':'Declined by Admin';
  requestCopyForUser(user,request);
  if(approve&&request.type==='Deposit') { user.wallet.available=Number(user.wallet.available||0)+Number(request.amount); user.wallet.deposits=Number(user.wallet.deposits||0)+Number(request.amount); addActivity(db,user,'Deposit','Admin-authenticated deposit',Number(request.amount),{note:request.method||'Deposit'}); }
  else if(approve&&request.type==='Withdrawal') { user.wallet.available-=Number(request.amount); user.wallet.withdrawals=Number(user.wallet.withdrawals||0)+Number(request.amount); addActivity(db,user,'Withdrawal','Admin-authenticated withdrawal',-Number(request.amount),{note:request.reference||'Withdrawal'}); }
  else addActivity(db,user,request.type,`${request.type} request ${approve?'approved':'rejected'}`,0,{note:request.reviewNote});
  save(); toast(`${request.type} request ${approve?'authenticated':'rejected'}.`); render();
}
function applyWalletAdjustment(values) {
  const user=findUser(db,String(values.get('userId')||'')); if(!user) throw new Error('Select a registered user.');
  const field=String(values.get('field')||'available'), operation=String(values.get('operation')||'add'), amount=Number(values.get('amount'));
  if (!(amount>=0)) throw new Error('Enter a valid amount.');
  const before=Number(user.wallet[field]||0); let next=operation==='set'?amount:operation==='subtract'?before-amount:before+amount;
  if(next<0) throw new Error('This adjustment would move the balance below zero.');
  user.wallet[field]=next;
  if(field==='invested'&&next>before){ const added=next-before; const existing=user.holdings.find((h)=>h.assetClass==='US Equity'); if(existing){existing.value+=added;existing.costBasis+=added;} else user.holdings.push({id:newId('holding'),assetClass:'US Equity',ticker:'GVUS',name:'US Equity allocation',value:added,costBasis:added,ytd:8.2,expenseRatio:.04}); }
  const delta=next-before, label={available:'Available balance',invested:'Investment value',earnings:'Earnings'}[field]||field;
  addActivity(db,user,'Admin adjustment',`${label} ${operation==='set'?'set':operation==='add'?'increased':'reduced'} by Admin`,delta,{note:String(values.get('note')||'Administrator wallet adjustment')});
  save(); return {user,label,delta};
}
function sendMessage(userId,sender,text) {
  const message={id:newId('msg'),userId,sender,text:String(text).trim(),createdAt:new Date().toISOString(),read:false};
  if(!message.text)return;
  db.messages.push(message); save();
  if(backendAvailable&&serverMode)apiMutation('/messages',{userId,text:message.text}).catch(error=>console.warn('Message sync failed:',error.message));
  return message;
}
async function saveProfile() {
  const user=currentUser(), name=$('#profile-name')?.value.trim(), email=$('#profile-email')?.value.trim().toLowerCase();
  if(!name||!email?.includes('@')){toast('Enter a name and valid email address.','error');return;}
  const clash=db.users.find((u)=>u.id!==user.id&&u.email.toLowerCase()===email); if(clash){toast('That email address belongs to another account.','error');return;}
  try{await apiMutation('/state',{state:{profile:{name,email}}},'PUT');}catch(error){toast(error.message,'error');return;}
  user.name=name; user.email=email; user.settings.plan=$('#profile-plan')?.value||user.settings.plan; user.settings.risk=$('#profile-risk')?.value||user.settings.risk; save(); toast('Profile settings saved.'); render();
}
function doConfirm() {
  const action=modal?.data?.onConfirm;
  if(typeof action==='function') action(); else closeModal();
}
function confirmDialog({title,body,confirmLabel='Confirm',onConfirm}) { setModal('confirm',{title,body,confirmLabel,onConfirm}); }
function openPropertyFunding(propertyId) {
  const p=propertyById(propertyId); const user=currentUser();
  const goal=user?.goals.slice().sort((a,b)=>Math.abs(a.target-p.base)-Math.abs(b.target-p.base))[0];
  if(goal) setModal('goal-detail',{id:goal.id}); else setModal('goal-form');
}
function openUserThread(userId) { modal=null; pageState.adminTab='Messages'; pageState.adminThreadUser=userId; currentRoute='Admin Console'; render(); }
function exportActivity() {
  const rows=getTransactions(currentUser()); const header=['Date','Type','Description','Amount','Reference'];
  const lines=[header,...rows.map((r)=>[r.date,r.type,r.title,r.amount,r.reference||r.id])].map((row)=>row.map((v)=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\n');
  const url=URL.createObjectURL(new Blob([lines],{type:'text/csv;charset=utf-8'})), link=document.createElement('a'); link.href=url; link.download='goal-system-activity.csv'; link.click(); URL.revokeObjectURL(url); toast('Activity ledger exported.');
}
function handleClick(event) {
  const routeTarget=event.target.closest('[data-route]');
  if(routeTarget){event.preventDefault();const route=routeTarget.dataset.route;if(routeTarget.dataset.scroll){navigate(route);setTimeout(()=>$('#'+routeTarget.dataset.scroll)?.scrollIntoView({behavior:'smooth'}),80);}else navigate(route);return;}
  const modeTarget=event.target.closest('[data-auth-mode]');
  if(modeTarget){event.preventDefault();if(modal?.type==='auth'){authMode=modeTarget.dataset.authMode;authError='';render();}else setModal('auth',{mode:modeTarget.dataset.authMode});return;}
  const button=event.target.closest('[data-action]'); if(!button)return;
  const action=button.dataset.action, id=button.dataset.id;
  switch(action){
    case 'auth-open': setModal('auth',{mode:button.dataset.authMode||'signin'}); break;
    case 'modal-close': closeModal(); break;
    case 'modal-backdrop': if(event.target===button)closeModal(); break;
    case 'password-toggle': {const field=$('#'+button.dataset.target);if(field){field.type=field.type==='password'?'text':'password';button.textContent=field.type==='password'?'Show':'Hide';}break;}
    case 'reset-open': setModal('reset'); break;
    case 'logout': if(backendAvailable&&serverMode)apiMutation('/auth/sign-out',{}).catch(error=>console.warn('Sign-out sync failed:',error.message)); session=null; serverMode=false; serverUser=null; saveSession(null); currentRoute='Home'; modal=null; render(); toast('You have signed out.'); break;
    case 'public-nav': setModal('public-nav'); break;
    case 'wallet-open': setModal('wallet'); break;
    case 'cart-open': setModal('cart'); break;
    case 'goal-form': setModal('goal-form',{id:button.dataset.id||button.dataset.goal||''}); break;
    case 'goal-detail': setModal('goal-detail',{id}); break;
    case 'goal-delete': {const goal=currentUser()?.goals.find((g)=>g.id===id);if(goal)confirmDialog({title:'Delete this goal?',body:`Delete “${goal.name}” and remove it from your workspace?`,confirmLabel:'Delete goal',onConfirm:()=>{const user=currentUser();user.goals=user.goals.filter((g)=>g.id!==id);save();modal=null;toast('Goal deleted.');render();}});break;}
    case 'deposit': setModal('deposit'); break;
    case 'withdraw': setModal('withdraw'); break;
    case 'transfer': setModal('transfer'); break;
    case 'invest': setModal('invest',{goalId:button.dataset.goal||''}); break;
    case 'chat': setModal('chat'); if(backendAvailable&&serverMode)apiRequest('/messages').then(result=>{db.messages=db.messages.filter(m=>m.userId!==currentUser().id).concat(result.messages||[]);saveDatabase(db);if(modal?.type==='chat')render();}).catch(()=>{}); break;
    case 'open-notifications': setModal('notifications'); break;
    case 'save-property': toggleSavedProperty(id); break;
    case 'property-saved': pageState.propertySaved=!pageState.propertySaved;render();break;
    case 'property-detail': setModal('property-detail',{id}); break;
    case 'property-funding': openPropertyFunding(id); break;
    case 'clear-property-filters': pageState.propertySearch='';pageState.propertyStatus='All status';pageState.propertyType='All types';pageState.propertyBeds='Any beds';pageState.propertyMax='';pageState.propertySaved=false;render();break;
    case 'product-detail': if(productById(id))setModal('product-detail',{id}); break;
    case 'cart-qty': adjustCart(id,button.dataset.variant,Number(button.dataset.delta)); break;
    case 'cart-remove': removeCartItem(id,button.dataset.variant); break;
    case 'cart-clear': confirmDialog({title:'Clear your cart?',body:'All items will be removed from your cart.',confirmLabel:'Clear cart',onConfirm:()=>{const user=currentUser();user.cart=[];save();modal=null;toast('Your cart has been cleared.');render();}}); break;
    case 'checkout-open': modal={type:'checkout'};render();break;
    case 'shop-category': pageState.shopCategory=button.dataset.category;render();break;
    case 'stock-watch-filter': pageState.stockWatchlist=!pageState.stockWatchlist;render();break;
    case 'watch-stock': {const user=currentUser(),symbol=button.dataset.symbol;user.watchlist||=[];user.watchlist=user.watchlist.includes(symbol)?user.watchlist.filter((s)=>s!==symbol):[...user.watchlist,symbol];save();render();toast(`${symbol} ${user.watchlist.includes(symbol)?'added to':'removed from'} your watchlist.`);break;}
    case 'market-symbol': {const stock=STOCKS.find((s)=>s.symbol===button.dataset.symbol);if(stock)toast(`${stock.name} · ${money(quote(stock.base,stock.symbol,.016))} · ${formatPercent(dailyChange(stock.symbol,5.6))}`);break;}
    case 'crypto-symbol': {const asset=CRYPTOS.find((s)=>s.symbol===button.dataset.symbol);if(asset)toast(`${asset.name} · ${money(quote(asset.base,asset.symbol,.028,asset.base<.01?7:2))} · ${formatPercent(dailyChange(asset.symbol,12.5))}`);break;}
    case 'crypto-watch-info': toast('Explore by category, market cap, volume, dominance and total value locked.'); break;
    case 'sort-holding': pageState.holdingDirection=pageState.holdingSort===button.dataset.sortHolding&&pageState.holdingDirection==='desc'?'asc':'desc';pageState.holdingSort=button.dataset.sortHolding;render();break;
    case 'admin-tab': pageState.adminTab=button.dataset.tab;modal=null;currentRoute='Admin Console';render();break;
    case 'user-create': setModal('user-create'); break;
    case 'user-edit': setModal('user-edit',{id}); break;
    case 'user-detail': setModal('user-detail',{id}); break;
    case 'user-thread': openUserThread(id); break;
    case 'user-delete': {const target=findUser(db,id);if(target)confirmDialog({title:'Delete user account?',body:`Remove ${target.name} (@${target.username}) and their associated local account records?`,confirmLabel:'Delete user',onConfirm:()=>removeUser(id)});break;}
    case 'request-approve': approveRequest(id,true); break;
    case 'request-reject': approveRequest(id,false); break;
    case 'announcement-create': setModal('announcement'); break;
    case 'announcement-delete': {const item=db.announcements.find((a)=>a.id===id);if(item)confirmDialog({title:'Delete announcement?',body:`Delete “${item.title}” from member dashboards?`,confirmLabel:'Delete announcement',onConfirm:()=>{if(backendAvailable&&serverMode)apiMutation(`/admin/announcements/${id}`,{},'DELETE').catch(error=>toast(error.message,'error'));db.announcements=db.announcements.filter((a)=>a.id!==id);save();modal=null;toast('Announcement deleted.');render();}});break;}
    case 'method-create': setModal('method'); break;
    case 'method-delete': {const method=db.paymentMethods.find((m)=>m.id===id);if(method)confirmDialog({title:'Remove payment method?',body:`Remove ${method.name} from the available deposit methods?`,confirmLabel:'Remove method',onConfirm:()=>{if(backendAvailable&&serverMode)apiMutation(`/admin/payment-methods/${id}`,{},'DELETE').catch(error=>toast(error.message,'error'));db.paymentMethods=db.paymentMethods.filter((m)=>m.id!==id);save();modal=null;toast('Payment method removed.');render();}});break;}
    case 'adjust-open': setModal('adjust',{userId:button.dataset.user||''}); break;
    case 'setting-toggle': {const user=currentUser();const key=button.dataset.key;user.settings[key]=!user.settings[key];save();render();toast(`${key==='autoInvest'?'Auto-invest':key==='roundUps'?'Round-ups':key==='emailAlerts'?'Email notifications':'In-app notifications'} ${user.settings[key]?'enabled':'disabled'}.`);break;}
    case 'settings-save': saveProfile(); break;
    case 'activity-export': exportActivity(); break;
    case 'confirm-action': doConfirm(); break;
    default: break;
  }
}
function refreshPreservingFocus(element) {
  const id=element.id, start=element.selectionStart, end=element.selectionEnd, value=element.value;
  render(); const replacement=$('#'+id); if(replacement){replacement.focus();if(typeof start==='number'&&replacement.setSelectionRange)replacement.setSelectionRange(start,end);}
}
function handleInput(event) {
  const el=event.target;
  if(el.id==='stock-search'){pageState.stockSearch=el.value;refreshPreservingFocus(el);}
  else if(el.id==='crypto-search'){pageState.cryptoSearch=el.value;refreshPreservingFocus(el);}
  else if(el.id==='property-search'){pageState.propertySearch=el.value;refreshPreservingFocus(el);}
  else if(el.id==='property-max'){pageState.propertyMax=el.value;refreshPreservingFocus(el);}
  else if(el.id==='shop-search'){pageState.shopSearch=el.value;refreshPreservingFocus(el);}
  else if(el.id==='activity-search'){pageState.activitySearch=el.value;refreshPreservingFocus(el);}
  else if(el.id==='sim-contribution'){pageState.simulatorContribution=Number(el.value);refreshPreservingFocus(el);}
  else if(el.id==='sim-return'){pageState.simulatorReturn=Number(el.value);refreshPreservingFocus(el);}
  else if(el.id==='sim-years'){pageState.simulatorYears=Number(el.value);refreshPreservingFocus(el);}
  else if(el.id==='goal-target'){const tier=tierFor(Number(el.value));const item=TIERS.find((t)=>t.name===tier);const hint=$('#goal-tier-hint');if(hint&&item)hint.textContent=`${item.name} tier · ${money(item.min)} – ${money(item.max)}`;}
}
function handleChange(event) {
  const el=event.target;
  const selects={
    'stock-exchange':['stockExchange'],'stock-sector':['stockSector'],'stock-focus':['stockFocus'],
    'crypto-category':['cryptoCategory'],'crypto-sort':['cryptoSort'],
    'property-status':['propertyStatus'],'property-type':['propertyType'],'property-beds':['propertyBeds'],
    'activity-type':['activityType'],'sim-goal':[]
  };
  const key=selects[el.id]?.[0]; if(key){pageState[key]=el.value;render();}
  else if(el.id==='sim-goal'){const user=currentUser(),goal=user?.goals.find((g)=>g.id===el.value);if(goal){pageState.simulatorContribution=Number(goal.monthly||pageState.simulatorContribution);render();}}
  else if(el.id==='checkout-delivery'){const summary=$('.checkout-summary');if(summary){const data=cartTotals();const charge=el.value==='Priority delivery'?25:0;const ship=el.value==='Pickup'?0:data.shipping+charge;const due=data.goods+ship+data.tax+data.deposits;summary.querySelectorAll('.summary-row').forEach((row)=>{if(row.firstElementChild?.textContent==='Shipping & tax')row.lastElementChild.textContent=money(ship+data.tax);if(row.classList.contains('total'))row.lastElementChild.textContent=money(due);});}}
}
async function handleSubmit(event) {
  const form=event.target; event.preventDefault();
  switch(form.id){
    case 'auth-form': await handleAuthSubmit(form); break;
    case 'reset-form': await handleResetSubmit(form); break;
    case 'goal-form': handleGoalSubmit(form); break;
    case 'deposit-form': await handleDepositSubmit(form); break;
    case 'withdraw-form': await handleWithdrawSubmit(form); break;
    case 'transfer-form': await handleTransferSubmit(form); break;
    case 'invest-form': await handleInvestSubmit(form); break;
    case 'product-add-form': handleProductAdd(form); break;
    case 'checkout-form': await completeCheckout(form); break;
    case 'user-chat-form': {const values=new FormData(form);sendMessage(currentUser().id,'user',values.get('message'));render();break;}
    case 'admin-chat-form': {const values=new FormData(form);const id=pageState.adminThreadUser;sendMessage(id,'admin',values.get('message'));db.messages.filter((m)=>m.userId===id&&m.sender==='user').forEach((m)=>m.read=true);save();render();break;}
    case 'admin-user-form': await createAdminUser(form); break;
    case 'announcement-form': {const values=new FormData(form),item={title:String(values.get('title')).trim(),body:String(values.get('body')).trim(),audience:String(values.get('audience')||'all'),level:String(values.get('level')||'Update')};let remote=null;try{remote=await apiMutation('/admin/announcements',item);}catch(error){toast(error.message,'error');break;}db.announcements.unshift({id:remote?.announcement?.id||newId('ann'),...item,author:'Admin',createdAt:remote?.announcement?.created_at||new Date().toISOString()});save();modal=null;pageState.adminTab='Announcements';toast('Announcement sent.');render();break;}
    case 'method-form': {const values=new FormData(form),item={name:String(values.get('name')).trim(),detail:String(values.get('detail')).trim(),time:String(values.get('time')||'Processing time varies'),fee:String(values.get('fee')||'Fees may apply')};let remote=null;try{remote=await apiMutation('/admin/payment-methods',item);}catch(error){toast(error.message,'error');break;}db.paymentMethods.push({id:remote?.method?.id||newId('method'),...item});save();modal=null;pageState.adminTab='Deposit methods';toast('Deposit method added.');render();break;}
    case 'adjust-form': {const values=new FormData(form);try{await apiMutation('/admin/wallet-adjustment',{userId:values.get('userId'),field:values.get('field'),operation:values.get('operation'),amount:values.get('amount'),note:values.get('note')});const result=applyWalletAdjustment(values);modal=null;toast(`${result.label} adjusted for @${result.user.username}.`);render();}catch(error){const field=$('#adjust-error');field.textContent=error.message;field.classList.add('show');}break;}
    default: break;
  }
}
function requestCopyForUser(user,request){user.requests||=[];const i=user.requests.findIndex(x=>x.id===request.id);if(i>=0)user.requests[i]={...request};else user.requests.push({...request});}
async function handleAuthSubmit(form){return submitAuth(form);}
