function handleGoalSubmit(form){const user=currentUser(),values=new FormData(form),id=modal.data?.id,target=Number(values.get('target')),current=Number(values.get('current')),monthly=Number(values.get('monthly'));if(target<100||target>10_000_000){toast('Goal targets must be between $100 and $10,000,000.','error');return;}if(current<0||current>target){toast('Current amount must be between $0 and the target amount.','error');return;}const record={name:String(values.get('name')||'').trim(),target,current,monthly:Math.max(0,monthly),targetDate:String(values.get('targetDate')||''),risk:String(values.get('risk')||'Balanced'),allocation:String(values.get('allocation')||'Balanced portfolio'),updatedAt:new Date().toISOString()};if(!record.name){toast('Give your goal a name to continue.','error');return;}const existing=user.goals.find(g=>g.id===id);if(existing)Object.assign(existing,record);else user.goals.unshift({id:newId('goal'),...record,createdAt:new Date().toISOString()});user.settings.plan=tierFor(target);save();modal=null;toast(existing?'Goal updated.':'Your goal is ready to grow.');render();}
async function handleDepositSubmit(form){const user=currentUser(),values=new FormData(form),amount=Number(values.get('amount')),method=db.paymentMethods.find(m=>m.id===values.get('method'));if(amount<10){$('#deposit-error').textContent='Enter a deposit amount of at least $10.';$('#deposit-error').classList.add('show');return;}let remote=null;try{remote=await apiMutation('/wallet/deposit',{amount,method:method?.id,reference:String(values.get('reference')||'').trim()});}catch(error){$('#deposit-error').textContent=error.message;$('#deposit-error').classList.add('show');return;}createRequest(user,'Deposit',amount,{id:remote?.id,method:method?.name||'Payment method',reference:String(values.get('reference')||'').trim()});modal=null;toast('Deposit request submitted for review.');render();}
async function handleWithdrawSubmit(form){const user=currentUser(),values=new FormData(form),amount=Number(values.get('amount'));if(amount<10){$('#withdraw-error').textContent='Enter a withdrawal amount of at least $10.';$('#withdraw-error').classList.add('show');return;}if(amount>user.wallet.available){$('#withdraw-error').textContent='The requested amount is greater than your available balance.';$('#withdraw-error').classList.add('show');return;}let remote=null;try{remote=await apiMutation('/wallet/withdraw',{amount,holder:String(values.get('holder')||'').trim(),details:String(values.get('details')||'').trim(),note:String(values.get('reference')||'').trim()});}catch(error){$('#withdraw-error').textContent=error.message;$('#withdraw-error').classList.add('show');return;}createRequest(user,'Withdrawal',amount,{id:remote?.id,method:'Bank / wallet destination',reference:String(values.get('details')||'').trim(),holder:String(values.get('holder')||'').trim(),details:String(values.get('details')||'').trim(),note:String(values.get('reference')||'').trim()});modal=null;toast('Withdrawal request submitted for review.');render();}
async function handleTransferSubmit(form){const user=currentUser(),values=new FormData(form),username=String(values.get('username')||''),amount=Number(values.get('amount')),note=String(values.get('note')||'');try{const remote=await apiMutation('/wallet/transfer',{username,amount,note});if(backendAvailable&&serverMode){mergeServerUser(await apiRequest('/state'));modal=null;toast(`Transfer sent to @${remote.recipient.username}.`);render();return;}const to=createTransfer(user,username,amount,note);modal=null;toast(`Transfer sent to @${to.username}.`);render();}catch(error){const target=$('#transfer-error');target.textContent=error.message;target.classList.add('show');}}
async function handleInvestSubmit(form){const values=new FormData(form),amount=Number(values.get('amount')),assetClass=String(values.get('assetClass')||'US Equity'),goalId=String(values.get('goalId')||'');try{await apiMutation('/wallet/invest',{amount,assetClass,goalId});investAmount(currentUser(),amount,assetClass,goalId);modal=null;toast('Investment added to your portfolio.');render();}catch(error){const target=$('#invest-error');target.textContent=error.message;target.classList.add('show');}}
