refreshServerSession();
async function apiMutation(path,body={},method='POST'){if(!backendAvailable||!serverMode)return null;return apiRequest(path,{method,body});}
async function loadAdminServerData(){if(!backendAvailable||!serverMode||!isAdmin())return;try{const [usersResult,requestsResult,annResult,methodsResult]=await Promise.all([apiRequest('/admin/users'),apiRequest('/admin/requests'),apiRequest('/admin/announcements'),apiRequest('/admin/payment-methods')]);db.users=(usersResult.users||[]).map(remote=>{const old=findUser(db,remote.id)||createUserRecord({name:remote.name,username:remote.username,email:remote.email,passwordHash:null});Object.assign(old,remote,{role:'user',passwordHash:old.passwordHash||null});old.wallet=remote.wallet||old.wallet;old.settings={...old.settings,...(remote.settings||{})};old.goals=remote.goals||[];old.holdings=remote.holdings||[];old.activity=remote.activity||[];old.requests=remote.requests||[];old.cart=remote.cart||[];old.orders=remote.orders||[];old.savedProperties=remote.savedProperties||[];old.watchlist=remote.watchlist||[];return old;});db.requests=requestsResult.requests||[];db.announcements=(annResult.announcements||[]).map(a=>({...a,createdAt:a.created_at||a.createdAt}));db.paymentMethods=methodsResult.methods||[];db.activity=db.users.flatMap(u=>u.activity||[]);const threads=await Promise.all(db.users.map(async u=>{try{const result=await apiRequest(`/messages?userId=${encodeURIComponent(u.id)}`);return result.messages||[];}catch{return [];}}));db.messages=threads.flat();saveDatabase(db);render();}catch(error){console.warn('Admin data sync unavailable:',error.message);}}
